// draftHighlightKind is a Draft Highlight's kind as the page shows it: "No
// kind" for one logged without.
func draftHighlightKind(kind string) string {
	if kind == "" {
		return "No kind"
	}
	return kind
}

// draftHighlightRefusal is why the last log was refused, as a sentence, or ""
// when the page isn't coming back from one.
func (v goalView) draftHighlightRefusal() string {
	if !v.opens(formDraftHighlight) || v.FormError == "" {
		return ""
	}
	return sentence(plainReason(errors.New(v.FormError)))
}

// draftHighlightsLoggable reports whether the Goal takes Draft Highlights: it
// does while it still takes Check-ins to offer them at, so not once it is Done
// or Cancelled.
func draftHighlightsLoggable(g domain.Goal) bool {
	return g.Lifecycle != domain.LifecycleDone && g.Lifecycle != domain.LifecycleCancelled
}

